import re

def matches_simple_selector(node, sel):
    if not node.tag:
        return False
    # parse tag, id, classes, attrs from sel
    # e.g. div#main.foo.bar[data-role="post"]
    tag_match = re.match(r"^([a-zA-Z0-9_-]+)", sel)
    if tag_match:
        if node.tag != tag_match.group(1).lower():
            return False

    # check IDs
    id_matches = re.findall(r"#([a-zA-Z0-9_-]+)", sel)
    for id_val in id_matches:
        if node.attrs.get("id") != id_val:
            return False

    # check classes
    class_matches = re.findall(r"\.([a-zA-Z0-9_-]+)", sel)
    node_classes = node.attrs.get("class", "").split()
    for cls in class_matches:
        if cls not in node_classes:
            return False

    # check attributes
    attr_matches = re.findall(r"\[([a-zA-Z0-9_-]+)(?:=[\"\']?([^\"\'\]]+)[\"\']?)?\]", sel)
    for attr_name, attr_val in attr_matches:
        if attr_name not in node.attrs:
            return False
        if attr_val and node.attrs[attr_name] != attr_val:
            return False

    return True

print("Test matcher:")
'"}

