{"command":"cat << 'EOF' > /tmp/test_selector.py
import re

class DOMNode:
    def __init__(self, tag, attrs=None, parent=None):
        self.tag = tag.lower() if tag else None
        self.attrs = dict(attrs) if attrs else {}
        self.parent = parent
        self.children = []

def parse_compound_selector(compound_str):
    # e.g. "div#main.foo.bar[data-role=post]"
    # returns dict of requirements: tag, id, classes, attrs
    s = compound_str.strip()
    tag = None
    m = re.match(r"^([a-zA-Z0-9_-]+|\*)", s)
    if m:
        t = m.group(1)
        if t != "*":
            tag = t.lower()
        s = s[m.end():]

    ids = []
    classes = []
    attrs = [] # list of (name, op, val)

    while s:
        if s.startswith("#"):
            m = re.match(r"^#([a-zA-Z0-9_-]+)", s)
            if m:
                ids.append(m.group(1))
                s = s[m.end():]
            else:
                break
        elif s.startswith("."):
            m = re.match(r"^\.([a-zA-Z0-9_-]+)", s)
            if m:
                classes.append(m.group(1))
                s = s[m.end():]
            else:
                break
        elif s.startswith("["):
            m = re.match(r"^\[([a-zA-Z0-9_-]+)(?:([~^$*|]?=)(?:\"([^\"]*)\"|'([^']*)'|([^\]]+)))?\]", s)
            if m:
                aname = m.group(1).lower()
                op = m.group(2)
                val = m.group(3) or m.group(4) or m.group(5)
                attrs.append((aname, op, val))
                s = s[m.end():]
            else:
                break
        else:
            break
    return {"tag": tag, "ids": ids, "classes": classes, "attrs": attrs}

def matches_compound(node, reqs):
    if not node.tag:
        return False
    if reqs["tag"] and node.tag != reqs["tag"]:
        return False
    if reqs["ids"]:
        node_id = node.attrs.get("id", "")
        for i in reqs["ids"]:
            if node_id != i:
                return False
    if reqs["classes"]:
        node_classes = node.attrs.get("class", "").split()
        for c in reqs["classes"]:
            if c not in node_classes:
                return False
    if reqs["attrs"]:
        for aname, op, val in reqs["attrs"]:
            if aname not in node.attrs:
                return False
            if op:
                nval = node.attrs[aname]
                if op == "=" and nval != val:
                    return False
    return True

# Test
n = DOMNode("div", {"id": "main", "class": "container active", "data-role": "post"})
r = parse_compound_selector("div#main.container[data-role=post]")
print("Matches?", matches_compound(n, r))
