        [for --plugin-table] how tables containing newlines should be handled: "skip" or "preserve"

    --opt-table-presentation-tables
        [for --plugin-table] whether tables with role="presentation" should be converted

    --opt-table-skip-empty-rows
        [for --plugin-table] omit empty rows from the output

    --opt-table-span-cell-behavior
        [for --plugin-table] how colspan/rowspan should be rendered: "empty" or "mirror"

    --plugin-strikethrough
        enable the plugin ~~strikethrough~~

    --plugin-table
        enable the plugin table



For more information visit the documentation:
https://github.com/Johanneskaufmann/html-to-markdown

"""

class Options:
    def __init__(self):
        self.input_path = ""
        self.output_path = ""
        self.output_overwrite = False
        self.domain = ""
        self.exclude_selector = ""
        self.include_selector = ""
        self.opt_strong_delimiter = "**"
        self.opt_table_cell_padding_behavior = "aligned"
        self.opt_table_header_promotion = False
        self.opt_table_newline_behavior = "skip"
        self.opt_table_presentation_tables = False
        self.opt_table_skip_empty_rows = False
        self.opt_table_span_cell_behavior = "empty"
        self.plugin_strikethrough = False
        self.plugin_table = False

class DOMNode:
    def __init__(self, tag, attrs=None, parent=None):
        self.tag = tag.lower() if tag else None
        self.attrs = dict(attrs) if attrs else {}
        self.parent = parent
        self.children = []

    def get_text(self):
        res = []
        for c in self.children:
            if isinstance(c, str):
                res.append(c)
            else:
                res.append(c.get_text())
        return "".join(res)

class DOMBuilder(HTMLParser):
    VOID_TAGS = {"area", "base", "br", "col", "embed", "hr", "img", "input", "link", "meta", "param", "source", "track", "wbr"}
    RAW_TAGS = {"script", "style"}

    def __init__(self):
        super().__init__(convert_charrefs=False)
        self.root = DOMNode(None)
        self.current = self.root

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        if self.current.tag in self.RAW_TAGS:
            return
        node = DOMNode(tag, attrs, parent=self.current)
        self.current.children.append(node)
        if tag not in self.VOID_TAGS:
            self.current = node

    def handle_endtag(self, tag):
        tag = tag.lower()
        p = self.current
        while p and p.tag != tag:
            p = p.parent
        if p and p.parent:
            self.current = p.parent

    def handle_data(self, data):
        if self.current.tag in self.RAW_TAGS:
            return
        if data:
            if self.current.children and isinstance(self.current.children[-1], str):
                self.current.children[-1] += data
            else:
                self.current.children.append(data)

    def handle_entityref(self, name):
        self.handle_data(f"&{name};")

    def handle_charref(self, name):
        self.handle_data(f"&#{name};")

# Selector matching
def parse_compound_selector(compound_str):
    s = compound_str.strip()
    tag = None
    m = re.match(r"^([a-zA-Z0-9_-]+|\*)", s)
    if m:
        t = m.group(1)
        if t != "*":
            tag = t.lower()
        s = s[m.end():]

    ids = []
    classes = []
    attrs = []

    while s:
        if s.startswith("#"):
            m = re.match(r"^#([a-zA-Z0-9_-]+)", s)
            if m:
                ids.append(m.group(1))
                s = s[m.end():]
            else: break
        elif s.startswith("."):
            m = re.match(r"^\.([a-zA-Z0-9_-]+)", s)
            if m:
                classes.append(m.group(1))
                s = s[m.end():]
            else: break
        elif s.startswith("["):
            m = re.match(r"^\[([a-zA-Z0-9_-]+)(?:([~^$*|]?=)(?:\"([^\"]*)\"|'([^']*)'|([^\]]+)))?\]", s)
            if m:
                aname = m.group(1).lower()
                op = m.group(2)
                val = m.group(3) or m.group(4) or m.group(5)
                attrs.append((aname, op, val))
                s = s[m.end():]
            else: break
        else: break
    return {"tag": tag, "ids": ids, "classes": classes, "attrs": attrs}

def matches_compound(node, reqs):
    if not isinstance(node, DOMNode) or not node.tag:
        return False
    if reqs["tag"] and node.tag != reqs["tag"]:
        return False
    if reqs["ids"]:
        node_id = node.attrs.get("id", "")
        for i in reqs["ids"]:
            if node_id != i: return False
    if reqs["classes"]:
        node_classes = node.attrs.get("class", "").split()
        for c in reqs["classes"]:
            if c not in node_classes: return False
    if reqs["attrs"]:
        for aname, op, val in reqs["attrs"]:
            if aname not in node.attrs: return False
            if op:
                nval = node.attrs[aname]
                if op == "=" and nval != val: return False
    return True

def matches_single_chain(node, selector_str):
    tokens = re.split(r"(\s+>\s+|\s+)", selector_str.strip())
    tokens = [t for t in tokens if t.strip() or t == " > "]
    curr_node = node
    i = len(tokens) - 1
    while i >= 0:
        t = tokens[i]
        if t in (" > ", ">"):
            i -= 1
            if i < 0: return False
            comp = parse_compound_selector(tokens[i])
            curr_node = curr_node.parent
            if not curr_node or not matches_compound(curr_node, comp):
                return False
            i -= 1
        elif t.strip():
            comp = parse_compound_selector(t)
            if i == len(tokens) - 1:
                if not matches_compound(curr_node, comp): return False
            else:
                curr_node = curr_node.parent
                found = False
                while curr_node:
                    if matches_compound(curr_node, comp):
                        found = True
                        break
                    curr_node = curr_node.parent
                if not found: return False
            i -= 1
        else: i -= 1
    return True

def matches_selector(node, selector_str):
    if not selector_str or not isinstance(node, DOMNode):
        return False
    chains = [c.strip() for c in selector_str.split(",") if c.strip()]
    for chain in chains:
        if matches_single_chain(node, chain):
            return True
    return False

def find_matching_nodes(node, selector_str):
    res = []
    if isinstance(node, DOMNode):
        if matches_selector(node, selector_str):
            res.append(node)
        for c in node.children:
            res.extend(find_matching_nodes(c, selector_str))
    return res

def filter_excluded_nodes(node, exclude_selector):
    if not exclude_selector or not isinstance(node, DOMNode):
        return
    filtered = []
    for c in node.children:
        if isinstance(c, DOMNode):
            if not matches_selector(c, exclude_selector):
                filter_excluded_nodes(c, exclude_selector)
                filtered.append(c)
        else:
            filtered.append(c)
    node.children = filtered

# Converter
class HTMLToMarkdownConverter:
    def __init__(self, options):
        self.options = options

    def decode_text(self, text):
        s = html.unescape(text)
        s = s.replace("<", "&lt;").replace(">", "&gt;")
        return s

    def escape_markdown(self, text):
        s = self.decode_text(text)
        s = s.replace("\\", "\\\\")
        s = s.replace("`", "\\`")
        s = s.replace("[", "\\[")
        s = s.replace("]", "\\]")

        s = re.sub(r"(?<!\\)\*\*(?=\S)", r"\\*\\*", s)
        s = re.sub(r"(?<=\S)\*\*(?!\\)", r"\\**", s)
        s = re.sub(r"(?<!\\)\*(?=\S)", r"\\*", s)
        s = re.sub(r"(?<!\\)_(?=[a-zA-Z0-9])", r"\\_", s)

        lines = s.split("\n")
        escaped_lines = []
        for line in lines:
            l = line
            if re.match(r"^#{1,6}\s", l):
                l = "\\" + l
            elif re.match(r"^[\-\+]\s", l):
                l = "\\" + l
            elif re.match(r"^\d+\.\s", l):
                l = re.sub(r"^(\d+)\.", r"\1\\.", l)
            escaped_lines.append(l)
        return "\n".join(escaped_lines)

    def convert_node(self, node, in_pre=False, in_table=False, list_context=None):
        if isinstance(node, str):
            if in_pre:
                return node
            # Collapse whitespace in normal text
            text = node
            # Replace tabs/newlines with spaces in inline text
            text = re.sub(r"[\r\n\t]+", " ", text)
            text = re.sub(r" +", " ", text)
            return self.escape_markdown(text)

        if not isinstance(node, DOMNode) or not node.tag:
            return self.convert_children(node, in_pre, in_table, list_context)

        tag = node.tag

        if tag in ("script", "style", "head", "meta", "link", "title"):
            return ""

        if tag in ("h1", "h2", "h3", "h4", "h5", "h6"):
            level = int(tag[1])
            prefix = "#" * level + " "
            inner = self.convert_children(node, in_pre, in_table, list_context).strip()
            return f"\n\n{prefix}{inner}\n\n"

        if tag == "p":
            inner = self.convert_children(node, in_pre, in_table, list_context).strip()
            return f"\n\n{inner}\n\n"

        if tag in ("strong", "b"):
            delim = self.options.opt_strong_delimiter or "**"
            inner = self.convert_children(node, in_pre, in_table, list_context)
            if not inner.strip():
                return inner
            lspace = inner[:len(inner) - len(inner.lstrip())]
            rspace = inner[len(inner.rstrip()):]
            return f"{lspace}{delim}{inner.strip()}{delim}{rspace}"

        if tag in ("em", "i"):
            inner = self.convert_children(node, in_pre, in_table, list_context)
            if not inner.strip():
                return inner
            lspace = inner[:len(inner) - len(inner.lstrip())]
            rspace = inner[len(inner.rstrip()):]
            return f"{lspace}*{inner.strip()}*{rspace}"

        if tag in ("s", "del", "strike"):
            inner = self.convert_children(node, in_pre, in_table, list_context)
            if self.options.plugin_strikethrough:
                if not inner.strip():
                    return inner
                lspace = inner[:len(inner) - len(inner.lstrip())]
                rspace = inner[len(inner.rstrip()):]
                return f"{lspace}~~{inner.strip()}~~{rspace}"
            return inner

        if tag in ("code", "kbd", "samp"):
            if in_pre:
                return self.convert_children(node, True, in_table, list_context)
            code_str = node.get_text()
            if "`" in code_str:
                if code_str.startswith("`") or code_str.endswith("`"):
                    return f"`` {code_str} ``"
                return f"``{code_str}``"
            return f"`{code_str}`"

        if tag == "pre":
            # Extract language from class if any
            lang = ""
            code_child = None
            for c in node.children:
                if isinstance(c, DOMNode) and c.tag == "code":
                    code_child = c
                    break
            target = code_child or node
            cls_val = target.attrs.get("class", "")
            m = re.search(r"\b(?:language|lang)-([a-zA-Z0-9_-]+)\b", cls_val)
            if m:
                lang = m.group(1)

            code_str = target.get_text() if code_child else node.get_text()
            fence = "```"
            if "```" in code_str:
                fence = "````"
            return f"\n\n{fence}{lang}\n{code_str}\n{fence}\n\n"

        if tag == "a":
            href = node.attrs.get("href", "")
            title = node.attrs.get("title", "")
            if href:
                if self.options.domain:
                    href = urllib.parse.urljoin(self.options.domain, href)
                inner = self.convert_children(node, in_pre, in_table, list_context).strip()
                title_part = f' "{title}"' if title else ""
                return f"[{inner}]({href}{title_part})"
            return self.convert_children(node, in_pre, in_table, list_context)

        if tag == "img":
            src = node.attrs.get("src", "")
            alt = node.attrs.get("alt", "")
            title = node.attrs.get("title", "")
            if src and self.options.domain:
                src = urllib.parse.urljoin(self.options.domain, src)
            title_part = f' "{title}"' if title else ""
            return f"![{alt}]({src}{title_part})"

        if tag == "hr":
            return "\n\n* * *\n\n"

        if tag in ("br", "br/"):
            if in_table and self.options.opt_table_newline_behavior == "preserve":
                return "<br />"
            return "  \n"

        if tag == "blockquote":
            inner = self.convert_children(node, in_pre, in_table, list_context).strip()
            lines = inner.split("\n")
            prefixed = []
            for l in lines:
                if l.strip():
                    prefixed.append(f"> {l}")
                else:
                    prefixed.append(">")
            return "\n\n" + "\n".join(prefixed) + "\n\n"

        if tag == "ul":
            items = []
            for c in node.children:
                if isinstance(c, DOMNode) and c.tag == "li":
                    item_str = self.convert_node(c, in_pre, in_table, list_context={"type": "ul", "index": 1}).strip()
                    items.append(f"- {item_str}")
            return "\n\n" + "\n".join(items) + "\n\n"

        if tag == "ol":
            items = []
            try:
                start_idx = int(node.attrs.get("start", "1"))
            except ValueError:
                start_idx = 1
            idx = start_idx
            for c in node.children:
                if isinstance(c, DOMNode) and c.tag == "li":
                    item_str = self.convert_node(c, in_pre, in_table, list_context={"type": "ol", "index": idx}).strip()
                    items.append(f"{idx}. {item_str}")
                    idx += 1
            return "\n\n" + "\n".join(items) + "\n\n"

        if tag == "li":
            return self.convert_children(node, in_pre, in_table, list_context)

        if tag == "table":
            if not self.options.plugin_table or (node.attrs.get("role") == "presentation" and not self.options.opt_table_presentation_tables):
                # Render as plain text
                return self.convert_children(node, in_pre, False, list_context)
            return "\n\n" + self.render_table(node) + "\n\n"

        return self.convert_children(node, in_pre, in_table, list_context)

    def convert_children(self, node, in_pre=False, in_table=False, list_context=None):
        if not isinstance(node, DOMNode):
            return ""
        res = []
        for c in node.children:
            res.append(self.convert_node(c, in_pre, in_table, list_context))
        return "".join(res)

    def render_table(self, table_node):
        # Extract rows and cells
        rows = []

        def collect_rows(n):
            if not isinstance(n, DOMNode): return
            if n.tag == "tr":
                rows.append(n)
            else:
                for c in n.children:
                    collect_rows(c)
        collect_rows(table_node)

        if not rows:
            return ""

        # Parse table cells
        grid = []
        alignments = []

        first_row_cells = [c for c in rows[0].children if isinstance(c, DOMNode) and c.tag in ("th", "td")]
        has_th_first_row = any(c.tag == "th" for c in first_row_cells)
        has_thead = any(isinstance(c, DOMNode) and c.tag == "thead" for c in table_node.children)

        has_header = has_thead or has_th_first_row or self.options.opt_table_header_promotion

        for r in rows:
            row_cells = []
            for c in r.children:
                if isinstance(c, DOMNode) and c.tag in ("th", "td"):
                    # Check align attr
                    align = c.attrs.get("align", "").lower()
                    cell_text = self.convert_children(c, False, True).strip()
                    cell_text = cell_text.replace("\n", " ")
                    colspan = 1
                    try:
                        colspan = int(c.attrs.get("colspan", "1"))
                    except ValueError: pass

                    row_cells.append({"text": cell_text, "align": align, "colspan": colspan})
            if row_cells:
                grid.append(row_cells)

        if not grid:
            return ""

        # Alignments
        max_cols = max(sum(cell["colspan"] for cell in row) for row in grid)
        if has_header and grid:
            for cell in grid[0]:
                for _ in range(cell["colspan"]):
                    alignments.append(cell["align"])
        while len(alignments) < max_cols:
            alignments.append("")

        # Expand spans
        expanded_grid = []
        for row in grid:
            exp_row = []
            for cell in row:
                if cell["colspan"] > 1:
                    exp_row.append(cell["text"])
                    fill = cell["text"] if self.options.opt_table_span_cell_behavior == "mirror" else ""
                    for _ in range(cell["colspan"] - 1):
                        exp_row.append(fill)
                else:
                    exp_row.append(cell["text"])
            while len(exp_row) < max_cols:
                exp_row.append("")
            expanded_grid.append(exp_row)

        if not has_header:
            header_row = [""] * max_cols
            expanded_grid.insert(0, header_row)

        # Skip empty rows if requested
        if self.options.opt_table_skip_empty_rows:
            new_grid = [expanded_grid[0]] # keep header
            for row in expanded_grid[1:]:
                if any(cell.strip() for cell in row):
                    new_grid.append(row)
            expanded_grid = new_grid

        # Calculate col widths
        col_widths = [0] * max_cols
        for row in expanded_grid:
            for i, cell in enumerate(row):
                col_widths[i] = max(col_widths[i], len(cell))

        pad_behavior = self.options.opt_table_cell_padding_behavior
        for i in range(max_cols):
            min_len = 3
            if pad_behavior == "aligned":
                col_widths[i] = max(col_widths[i], min_len)
            else:
                col_widths[i] = max(col_widths[i], 1)

        # Render rows
        rendered_lines = []
        for row_idx, row in enumerate(expanded_grid):
            cell_strs = []
            for col_idx, cell in enumerate(row):
                w = col_widths[col_idx]
                align = alignments[col_idx] if col_idx < len(alignments) else ""

                if pad_behavior == "aligned":
                    if align == "right":
                        txt = cell.rjust(w)
                    elif align == "center":
                        txt = cell.center(w)
                    else:
                        txt = cell.ljust(w)
                    cell_strs.append(f" {txt} ")
                elif pad_behavior == "minimal":
                    cell_strs.append(f" {cell} ")
                else: # none
                    cell_strs.append(f"{cell}")

            rendered_lines.append("|" + "|".join(cell_strs) + "|")

            # Header divider row
            if row_idx == 0:
                div_strs = []
                for col_idx in range(max_cols):
                    w = col_widths[col_idx]
                    align = alignments[col_idx] if col_idx < len(alignments) else ""
                    if pad_behavior in ("minimal", "none"):
                        w = 3

                    if align == "left":
                        d = ":" + "-" * (w - 1)
                    elif align == "right":
                        d = "-" * (w - 1) + ":"
                    elif align == "center":
                        d = ":" + "-" * (w - 2) + ":"
                    else:
                        d = "-" * w

                    if pad_behavior != "none":
                        div_strs.append(d)
                    else:
                        div_strs.append(d)

                if pad_behavior == "aligned":
                    rendered_lines.append("|" + "|".join("-" + d + "-" for d in div_strs) + "|")
                elif pad_behavior == "minimal":
                    rendered_lines.append("|" + "|".join(div_strs) + "|")
                else:
                    rendered_lines.append("|" + "|".join(div_strs) + "|")

        return "\n".join(rendered_lines)

    def convert_html(self, html_content):
        builder = DOMBuilder()
        builder.feed(html_content)
        root = builder.root

        # Exclude selector
        if self.options.exclude_selector:
            filter_excluded_nodes(root, self.options.exclude_selector)

        # Include selector
        if self.options.include_selector:
            matched = find_matching_nodes(root, self.options.include_selector)
            if not matched:
                return "\n"
            parts = [self.convert_node(n).strip() for n in matched]
            out = "\n\n".join(p for p in parts if p)
        else:
            out = self.convert_node(root).strip()

        # Normalize multiple block newlines
        out = re.sub(r"\n{3,}", "\n\n", out)
        if out:
            return out + "\n"
        return "\n"

# CLI Argument parsing
def main():
    args = sys.argv[1:]

    # Pre-check --version and --help
    if "-v" in args or "--version" in args:
        sys.stdout.write(VERSION_TEXT)
        sys.exit(0)

    if "-h" in args or "--help" in args or "-help" in args:
        sys.stdout.write(HELP_TEXT)
        sys.exit(0)

    options = Options()
    specified_opt_tables = []

    i = 0
    unknown_args = []

    while i < len(args):
        arg = args[i]

        if arg.startswith("-"):
            flag_name = arg
            flag_val = None
            if "=" in arg:
                flag_name, flag_val = arg.split("=", 1)

            if flag_name == "--input":
                if flag_val is None:
                    if i + 1 < len(args):
                        flag_val = args[i + 1]
                        i += 1
                    else:
                        sys.stderr.write("\nerror: flag needs an argument: -input\n\n")
                        sys.exit(1)
                options.input_path = flag_val

            elif flag_name == "--output":
                if flag_val is None:
                    if i + 1 < len(args):
                        flag_val = args[i + 1]
                        i += 1
                    else:
                        sys.stderr.write("\nerror: flag needs an argument: -output\n\n")
                        sys.exit(1)
                options.output_path = flag_val

            elif flag_name == "--output-overwrite":
                options.output_overwrite = True

            elif flag_name == "--domain":
                if flag_val is None:
                    if i + 1 < len(args):
                        flag_val = args[i + 1]
                        i += 1
                    else:
                        sys.stderr.write("\nerror: flag needs an argument: -domain\n\n")
                        sys.exit(1)
                options.domain = flag_val

            elif flag_name == "--exclude-selector":
                if flag_val is None:
                    if i + 1 < len(args):
                        flag_val = args[i + 1]
                        i += 1
                    else:
                        sys.stderr.write("\nerror: flag needs an argument: -exclude-selector\n\n")
                        sys.exit(1)
                options.exclude_selector = flag_val

            elif flag_name == "--include-selector":
                if flag_val is None:
                    if i + 1 < len(args):
                        flag_val = args[i + 1]
                        i += 1
                    else:
                        sys.stderr.write("\nerror: flag needs an argument: -include-selector\n\n")
                        sys.exit(1)
                options.include_selector = flag_val

            elif flag_name == "--opt-strong-delimiter":
                if flag_val is None:
                    if i + 1 < len(args):
                        flag_val = args[i + 1]
                        i += 1
                    else:
                        sys.stderr.write("\nerror: flag needs an argument: -opt-strong-delimiter\n\n")
                        sys.exit(1)
                options.opt_strong_delimiter = flag_val

            elif flag_name == "--opt-table-cell-padding-behavior":
                specified_opt_tables.append("opt-table-cell-padding-behavior")
                if flag_val is None:
                    if i + 1 < len(args):
                        flag_val = args[i + 1]
                        i += 1
                    else:
                        sys.stderr.write("\nerror: flag needs an argument: -opt-table-cell-padding-behavior\n\n")
                        sys.exit(1)
                options.opt_table_cell_padding_behavior = flag_val

            elif flag_name == "--opt-table-header-promotion":
                specified_opt_tables.append("opt-table-header-promotion")
                options.opt_table_header_promotion = True

            elif flag_name == "--opt-table-newline-behavior":
                specified_opt_tables.append("opt-table-newline-behavior")
                if flag_val is None:
                    if i + 1 < len(args):
                        flag_val = args[i + 1]
                        i += 1
                    else:
                        sys.stderr.write("\nerror: flag needs an argument: -opt-table-newline-behavior\n\n")
                        sys.exit(1)
                options.opt_table_newline_behavior = flag_val

            elif flag_name == "--opt-table-presentation-tables":
                specified_opt_tables.append("opt-table-presentation-tables")
                options.opt_table_presentation_tables = True

            elif flag_name == "--opt-table-skip-empty-rows":
                specified_opt_tables.append("opt-table-skip-empty-rows")
                options.opt_table_skip_empty_rows = True

            elif flag_name == "--opt-table-span-cell-behavior":
                specified_opt_tables.append("opt-table-span-cell-behavior")
                if flag_val is None:
                    if i + 1 < len(args):
                        flag_val = args[i + 1]
                        i += 1
                    else:
                        sys.stderr.write("\nerror: flag needs an argument: -opt-table-span-cell-behavior\n\n")
                        sys.exit(1)
                options.opt_table_span_cell_behavior = flag_val

            elif flag_name == "--plugin-strikethrough":
                options.plugin_strikethrough = True

            elif flag_name == "--plugin-table":
                options.plugin_table = True

            else:
                sys.stderr.write(f"\nerror: unknown flag: {arg}\n\n")
                sys.exit(1)
        else:
            unknown_args.append(arg)
        i += 1

    if unknown_args:
        sys.stderr.write(f"\nerror: unknown arguments: {' '.join(unknown_args)}\n\nHere is how you can use the CLI:\n\n    echo \"<strong>important</strong>\" | html2markdown\n\n")
        sys.exit(1)

    # Validate table options dependency
    if specified_opt_tables and not options.plugin_table:
        first_opt = specified_opt_tables[0]
        sys.stderr.write(f"\nerror: --{first_opt} requires --plugin-table to be enabled\n\n")
        sys.exit(1)

    # Validate plugin options when plugin-table enabled
    if options.plugin_table:
        if options.opt_table_cell_padding_behavior not in ("aligned", "minimal", "none", ""):
            sys.stderr.write(f'\nerror: error while initializing "table" plugin: unknown value "{options.opt_table_cell_padding_behavior}" for cell padding behavior\n\n')
            sys.exit(1)
        if options.opt_table_newline_behavior not in ("skip", "preserve", ""):
            sys.stderr.write(f'\nerror: error while initializing "table" plugin: unknown value "{options.opt_table_newline_behavior}" for newline behavior\n\n')
            sys.exit(1)
        if options.opt_table_span_cell_behavior not in ("empty", "mirror", ""):
            sys.stderr.write(f'\nerror: error while initializing "table" plugin: unknown value "{options.opt_table_span_cell_behavior}" for span cell behavior\n\n')
            sys.exit(1)

    # Validate strong delimiter
    if options.opt_strong_delimiter and options.opt_strong_delimiter not in ("**", "__"):
        sys.stderr.write(f'\nerror: invalid value for --opt-strong-delimiter="{options.opt_strong_delimiter}" must be exactly 2 characters of "**" or "__"\n\n')
        sys.exit(1)

    # Input handling
    input_files = []

    if not options.input_path:
        if sys.stdin.isatty():
            sys.stderr.write('\nerror: the html input should be piped into the cli\n\nHere is how you can use the CLI:\n\n    echo "<strong>important</strong>" | html2markdown\n\n')
            sys.exit(1)
        html_contents = [(None, sys.stdin.read())]
    else:
        pattern = options.input_path
        has_glob = any(c in pattern for c in ("*", "?", "["))

        if has_glob:
            input_files = sorted(glob.glob(pattern))
            if not input_files:
                sys.stderr.write(f'\nerror: no files found matching pattern "{pattern}"\n\nHere is how you can use a glob to match multiple files:\n\n    html2markdown --input "src/*.html" --output "dist/"\n\n')
                sys.exit(1)
            if len(input_files) >= 2:
                if not options.output_path:
                    sys.stderr.write(f'\nerror: when processing multiple input files --output needs to be a directory\n\nHere is how you can use a glob to match multiple files:\n\n    html2markdown --input "src/*.html" --output "dist/"\n\n')
                    sys.exit(1)
                if not options.output_path.endswith("/"):
                    sys.stderr.write(f'\nerror: when processing multiple input files, --output "{options.output_path}" must end with "{options.output_path}/" to indicate a directory\n\n')
                    sys.exit(1)
        else:
            if not os.path.exists(pattern):
                sys.stderr.write(f'\nerror: no files found matching pattern "{pattern}"\n\nHere is how you can use a glob to match multiple files:\n\n    html2markdown --input "src/*.html" --output "dist/"\n\n')
                sys.exit(1)
            if os.path.isdir(pattern):
                sys.stderr.write(f'\nerror: input path "{pattern}" is a directory, not a file\n\nHere is how you can use a glob to match multiple files:\n\n    html2markdown --input "src/*.html" --output "dist/"\n\n')
                sys.exit(1)
            input_files = [pattern]

        html_contents = []
        for fpath in input_files:
            with open(fpath, "r", encoding="utf-8", errors="replace") as f:
                html_contents.append((fpath, f.read()))

    converter = HTMLToMarkdownConverter(options)

    # Process outputs
    if len(html_contents) == 1 and not input_files and not options.output_path:
        # stdin to stdout
        markdown_out = converter.convert_html(html_contents[0][1])
        sys.stdout.write(markdown_out)
        return

    if len(html_contents) == 1 and input_files and not options.output_path:
        # single file to stdout
        markdown_out = converter.convert_html(html_contents[0][1])
        sys.stdout.write(markdown_out)
        return

    out_path = options.output_path
    if out_path.endswith("/"):
        os.makedirs(out_path, exist_ok=True)

        for src_path, content in html_contents:
            if src_path:
                base = os.path.basename(src_path)
                fname = os.path.splitext(base)[0] + ".md"
            else:
                fname = "output.md"

            target = os.path.join(out_path, fname)
            if os.path.exists(target) and not options.output_overwrite:
                sys.stderr.write(f'\nerror: output path "{out_path}" already exists. Use --output-overwrite to replace existing files\n\n')
                sys.exit(1)

            markdown_out = converter.convert_html(content)
            with open(target, "w", encoding="utf-8") as f:
                f.write(markdown_out)
    else:
        if os.path.isdir(out_path):
            base_name = os.path.basename(out_path.rstrip("/"))
            sys.stderr.write(f'\nerror: path "{base_name}" exists and is a directory, did you mean "{base_name}/"?\n\nThe --output must end with "/" to indicate a directory\n\n')
            sys.exit(1)

        if os.path.exists(out_path) and not options.output_overwrite:
            sys.stderr.write(f'\nerror: output path "{out_path}" already exists. Use --output-overwrite to replace existing files\n\n')
            sys.exit(1)

