        return self.convert_children(node, in_pre, in_table, list_context)

    def convert_children(self, node, in_pre=False, in_table=False, list_context=None):
        if not isinstance(node, DOMNode):
            return ""
        res = []
        for c in node.children:
            res.append(self.convert_node(c, in_pre, in_table, list_context))
        return "".join(res)

    def render_table(self, table_node):
        rows = []

        def collect_rows(n):
            if not isinstance(n, DOMNode): return
            if n.tag == "tr":
                rows.append(n)
            else:
                for c in n.children:
                    collect_rows(c)
