        has_thead = any(isinstance(c, DOMNode) and c.tag == "thead" for c in table_node.children)

        has_header = has_thead or has_th_first_row or self.options.opt_table_header_promotion

        for r in rows:
            row_cells = []
            for c in r.children:
                if isinstance(c, DOMNode) and c.tag in ("th", "td"):
                    align = c.attrs.get("align", "").lower()
                    cell_text = self.convert_children(c, False, True).strip()
                    cell_text = cell_text.replace("\n", " ")
                    colspan = 1
                    try:
                        colspan = int(c.attrs.get("colspan", "1"))
                    except ValueError: pass

                    row_cells.append({"text": cell_text, "align": align, "colspan": colspan})
            if row_cells:
                grid.append(row_cells)

        if not grid:
            return ""

        max_cols = max(sum(cell["colspan"] for cell in row) for row in grid)
        if has_header and grid:
            for cell in grid[0]:
                for _ in range(cell["colspan"]):
                    alignments.append(cell["align"])
        while len(alignments) < max_cols:
            alignments.append("")

        expanded_grid = []
        for row in grid:
            exp_row = []
            for cell in row:
                if cell["colspan"] > 1:
                    exp_row.append(cell["text"])
                    fill = cell["text"] if self.options.opt_table_span_cell_behavior == "mirror" else ""
                    for _ in range(cell["colspan"] - 1):
                        exp_row.append(fill)
                else:
                    exp_row.append(cell["text"])
            while len(exp_row) < max_cols:
                exp_row.append("")
            expanded_grid.append(exp_row)

        if not has_header:
            header_row = [""] * max_cols
            expanded_grid.insert(0, header_row)

        if self.options.opt_table_skip_empty_rows:
            new_grid = [expanded_grid[0]]
            for row in expanded_grid[1:]:
                if any(cell.strip() for cell in row):
                    new_grid.append(row)
