            m = re.match(r"^#([a-zA-Z0-9_-]+)", s)
            if m:
                ids.append(m.group(1))
                s = s[m.end():]
            else: break
        elif s.startswith("."):
            m = re.match(r"^\.([a-zA-Z0-9_-]+)", s)
            if m:
                classes.append(m.group(1))
                s = s[m.end():]
            else: break
        elif s.startswith("["):
            m = re.match(r"^\[([a-zA-Z0-9_-]+)(?:([~^$*|]?=)(?:\"([^\"]*)\"|'([^']*)'|([^\]]+)))?\]", s)
